+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storeState.lock) {
+            return storeState.properties.containsKey(rule.getDescription());
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (storeState.lock) {
+            String description = rule.getDescription();
+            String existingName = storeState.properties.getProperty(description);
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                forgetKnownRuleInRepair(description, existingName);
+                return;
+            }
+
+            String fileName = existingName != null ? existingName : createFileName(description);
+            validateWritableName(fileName);
+
+            write(violations, storeFolderPath.resolve(fileName));
+            if (existingName == null) {
+                storeState.properties.setProperty(description, fileName);
+                try {
+                    storeState.sync();
+                } catch (RuntimeException e) {
+                    storeState.properties.remove(description);
+                    tryDelete(storeFolderPath.resolve(fileName));
+                    throw e;
+                }
+                log.trace("Assigning new file {} to rule '{}'", fileName, description);
+            }
+        }
+    }
+
+    private String createFileName(String description) {
+        String fileName = ruleViolationFileNameStrategy.createRuleFileName(description);
+        if (fileName == null || fileName.isEmpty()) {
+            throw new StoreUpdateFailedException("RuleViolationFileNameStrategy returned no file name");
+        }
+        return fileName;
+    }
+
+    private void validateWritableName(String fileName) {
+        PathResolution resolution = resolve(fileName);
+        if (!resolution.valid || !resolution.direct) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Rule violation file name '%s' does not name a file directly in the store folder", fileName));
+        }
+        if (sameFileOrPath(resolution.path, storedRulesPath)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Rule violation file name '%s' leads to the store index", fileName));
+        }
+    }
+
+    private void forgetKnownRuleInRepair(String description, String existingName) {
+        if (existingName == null) {
+            return;
+        }
+        Entry entry = new Entry(description, existingName);
+        entry.path = inspect(existingName);
+        if (sameFileAsIndex(entry.path)) {
+            throw new StoreUpdateFailedException("Cannot remove a rule whose file name leads to the store index");
+        }
+        boolean shared = isShared(entry, storeState.properties);
+        if (!shared && entry.path.target != null) {
+            deleteTarget(entry.path.target, existingName);
+        }
+
+        storeState.properties.remove(description);
+        try {
+            storeState.sync();
+        } catch (RuntimeException e) {
+            storeState.properties.setProperty(description, existingName);
+            throw e;
+        }
+    }
