+    private void write(List<String> violations, Path ruleDetails) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append('\n');
+        }
+        try {
+            Files.write(ruleDetails, builder.toString().getBytes(UTF_8),
+                    StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
+        } catch (IOException | RuntimeException e) {
+            if (e instanceof StoreUpdateFailedException) {
+                throw (StoreUpdateFailedException) e;
+            }
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        StringBuilder result = new StringBuilder(violation.length());
+        for (int i = 0; i < violation.length(); i++) {
+            char character = violation.charAt(i);
+            if (character == '\\') {
+                result.append("\\\\");
+            } else if (character == '\r') {
+                result.append("\\r");
+            } else if (character == '\n') {
+                result.append("\\n");
+            } else {
+                result.append(character);
+            }
+        }
+        return result.toString();
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storeState.lock) {
+            String ruleDetailsFileName = storeState.properties.getProperty(rule.getDescription());
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(storeFolderPath.resolve(ruleDetailsFileName));
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(Path file) {
+        try {
+            return parseViolations(new String(Files.readAllBytes(file), UTF_8));
+        } catch (IOException | RuntimeException e) {
+            if (e instanceof StoreReadException) {
+                throw (StoreReadException) e;
+            }
+            throw new StoreReadException(e);
+        }
+    }
+
+    private List<String> parseViolations(String text) {
+        if (text.isEmpty() || isOnlyLineBreaks(text)) {
+            return Collections.emptyList();
+        }
+        List<String> result = new ArrayList<>();
+        StringBuilder current = new StringBuilder();
+        for (int i = 0; i < text.length(); i++) {
+            char character = text.charAt(i);
+            if (character == '\n') {
+                int precedingSlashes = 0;
+                for (int j = current.length() - 1; j >= 0 && current.charAt(j) == '\\'; j--) {
+                    precedingSlashes++;
+                }
+                if ((precedingSlashes & 1) == 1) {
+                    current.setLength(current.length() - 1);
+                    current.append('\n');
+                } else {
+                    addViolation(result, decode(current.toString()));
+                    current.setLength(0);
+                }
+            } else {
+                current.append(character);
+            }
+        }
+        addViolation(result, decode(current.toString()));
+        return result;
+    }
+
+    private void addViolation(List<String> result, String violation) {
+        // A CRLF line and a lone CR are line breaks when they are the whole file (and
+        // an empty CRLF line is not a violation). A CR occurring in actual text is kept.
+        if (!violation.isEmpty() && !"\r".equals(violation)) {
+            result.add(violation);
+        }
+    }
+
+    private String decode(String encoded) {
+        StringBuilder result = new StringBuilder(encoded.length());
+        for (int i = 0; i < encoded.length(); i++) {
+            char character = encoded.charAt(i);
+            if (character == '\\' && i + 1 < encoded.length()) {
+                char escaped = encoded.charAt(++i);
+                if (escaped == '\\') {
+                    result.append('\\');
+                } else if (escaped == 'r') {
+                    result.append('\r');
+                } else if (escaped == 'n') {
+                    result.append('\n');
+                } else {
+                    result.append('\\').append(escaped);
+                }
+            } else {
+                result.append(character);
+            }
+        }
+        return result.toString();
+    }
+
+    private IntegrityReport analyze(Properties properties) {
+        List<Entry> entries = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            entries.add(new Entry(description, properties.getProperty(description)));
+        }
+        entries.sort(Comparator.comparing(entry -> entry.description));
+
+        for (Entry entry : entries) {
+            entry.path = inspect(entry.name);
+            entry.broken = !entry.path.directRegularFile;
+            entry.resolved = !entry.broken && readLines(entry.path.target).isEmpty();
+            if (nameMode != NameMode.RANDOM) {
+                entry.derivedName = deriveName(entry.description);
+                entry.misplaced = !entry.name.equals(entry.derivedName);
+            }
+        }
+
+        Map<String, Integer> names = new HashMap<>();
+        Map<FileIdentity, Integer> files = new HashMap<>();
+        for (Entry entry : entries) {
+            names.put(entry.name, names.getOrDefault(entry.name, 0) + 1);
+            if (entry.path.identity != null) {
+                files.put(entry.path.identity, files.getOrDefault(entry.path.identity, 0) + 1);
+            }
+        }
+        for (Entry entry : entries) {
+            entry.shared = names.get(entry.name) > 1
+                    || (entry.path.identity != null && files.get(entry.path.identity) > 1);
+            if (entry.misplaced) {
+                entry.occupied = isOccupied(entry.derivedName, entries, entry);
+            }
+        }
+
+        Set<FileIdentity> ownedFiles = new HashSet<>();
+        for (Entry entry : entries) {
+            if (entry.path.identity != null) {
+                ownedFiles.add(entry.path.identity);
+            }
+        }
+        List<String> unownedFiles = findUnownedFiles(ownedFiles);
+        return new IntegrityReport(entries, unownedFiles);
+    }
+
+    private String deriveName(String description) {
+        String result = ruleViolationFileNameStrategy.createRuleFileName(description);
+        if (result == null || result.isEmpty()) {
+            throw new StoreInitializationFailedException(
+                    "RuleViolationFileNameStrategy returned no file name while checking store integrity");
+        }
+        return result;
+    }
+
+    private boolean isOccupied(String derivedName, List<Entry> entries, Entry current) {
+        for (Entry entry : entries) {
+            if (entry != current && derivedName.equals(entry.name)) {
+                return true;
+            }
+        }
+        PathResolution resolution = resolve(derivedName);
+        return !resolution.valid || !resolution.direct || resolution.exists;
+    }
+
+    private List<String> findUnownedFiles(Set<FileIdentity> ownedFiles) {
+        List<String> result = new ArrayList<>();
+        try (DirectoryStream<Path> stream = Files.newDirectoryStream(realStoreFolderPath)) {
+            for (Path child : stream) {
+                if (STORED_RULES_FILE_NAME.equals(child.getFileName().toString())
+                        || !Files.isRegularFile(child, LinkOption.NOFOLLOW_LINKS)) {
+                    continue;
+                }
+                FileIdentity identity = identityOf(child);
+                if (identity == null || !ownedFiles.contains(identity)) {
+                    result.add(child.getFileName().toString());
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        Collections.sort(result);
+        return result;
+    }
+
+    private void repair(IntegrityReport report) {
+        boolean indexChanged = false;
+        for (Entry entry : report.entries) {
+            if (entry.broken) {
+                storeState.properties.remove(entry.description);
+                indexChanged = true;
+            } else if (entry.resolved) {
+                if (!sameFileAsIndex(entry.path)) {
+                    if (!entry.shared && entry.path.target != null) {
+                        deleteTarget(entry.path.target, entry.name);
+                    }
+                    storeState.properties.remove(entry.description);
+                    indexChanged = true;
+                }
+            } else if (entry.misplaced && !entry.shared && !entry.occupied) {
+                moveTarget(entry.path.target, entry.derivedName);
+                storeState.properties.setProperty(entry.description, entry.derivedName);
+                indexChanged = true;
+            }
+        }
+        if (indexChanged) {
+            try {
+                storeState.sync();
+            } catch (RuntimeException e) {
+                throw new StoreInitializationFailedException(e);
+            }
+        }
+    }
+
+    private void moveTarget(Path target, String derivedName) {
+        if (target == null) {
+            throw new StoreInitializationFailedException("Cannot move a missing rule violation file");
+        }
+        Path destination = resolve(derivedName).path;
+        try {
+            Files.move(target, destination, StandardCopyOption.ATOMIC_MOVE);
+        } catch (IOException e) {
+            try {
+                Files.move(target, destination);
+            } catch (IOException fallback) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Cannot move rule violation file to '%s'", derivedName), fallback);
+            }
+        }
+    }
+
+    private void deleteTarget(Path target, String name) {
+        try {
+            if (sameFileOrPath(target, storedRulesPath)) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Rule violation file name '%s' leads to the store index", name));
+            }
+            Files.deleteIfExists(target);
+        } catch (StoreUpdateFailedException e) {
+            throw e;
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot delete rule violation file '%s'", name), e);
+        }
+    }
+
+    private void tryDelete(Path path) {
+        try {
+            if (existsWithoutFollowingLinks(path)) {
+                Files.delete(path);
+            }
+        } catch (IOException ignored) {
+            // The original update exception is the useful one to report.
+        }
+    }
+
+    private boolean isShared(Entry candidate, Properties properties) {
+        for (String description : properties.stringPropertyNames()) {
+            if (!description.equals(candidate.description)) {
+                String name = properties.getProperty(description);
+                if (candidate.name.equals(name)) {
+                    return true;
+                }
+                PathResolution candidatePath = inspect(candidate.name);
+                PathResolution otherPath = inspect(name);
+                if (candidatePath.identity != null && candidatePath.identity.equals(otherPath.identity)) {
+                    return true;
+                }
+            }
+        }
+        return false;
+    }
+
+    private EntryPath inspect(String name) {
+        PathResolution resolution = resolve(name);
+        return new EntryPath(resolution.direct && resolution.regular, resolution.direct && resolution.regular,
+                resolution.target, resolution.identity);
+    }
+
+    private PathResolution resolve(String name) {
+        try {
+            Path path = storeFolderPath.resolve(name);
+            boolean exists = existsWithoutFollowingLinks(path);
+            if (!exists) {
+                Path parent = path.normalize().getParent();
+                boolean direct = parent != null && realPathIfPossible(parent) != null
+                        && realStoreFolderPath.equals(realPathIfPossible(parent));
+                return new PathResolution(path, false, direct, false, null, null);
+            }
+            Path target = path.toRealPath();
+            BasicFileAttributes attributes = Files.readAttributes(target, BasicFileAttributes.class);
+            boolean regular = attributes.isRegularFile();
+            boolean direct = regular && realStoreFolderPath.equals(target.getParent());
+            return new PathResolution(path, true, direct, regular, target, identityOf(target, attributes));
+        } catch (InvalidPathException | IOException | SecurityException e) {
+            return new PathResolution(null, false, false, false, null, null);
+        }
+    }
+
+    private Path realPathIfPossible(Path path) {
+        try {
+            return path.toRealPath();
+        } catch (IOException | SecurityException e) {
+            return null;
+        }
+    }
+
+    private FileIdentity identityOf(Path path) {
+        try {
+            return identityOf(path, Files.readAttributes(path, BasicFileAttributes.class));
+        } catch (IOException e) {
+            return null;
+        }
+    }
+
+    private FileIdentity identityOf(Path path, BasicFileAttributes attributes) {
+        Object fileKey = attributes.fileKey();
+        return fileKey != null ? new FileIdentity(fileKey) : new FileIdentity(path.toAbsolutePath().normalize().toString());
+    }
+
+    private boolean sameFileAsIndex(EntryPath path) {
+        return path != null && path.target != null && sameFileOrPath(path.target, storedRulesPath);
+    }
+
+    private boolean sameFileOrPath(Path first, Path second) {
+        if (first == null || second == null) {
+            return false;
+        }
+        try {
+            if (Files.isSameFile(first, second)) {
+                return true;
+            }
+        } catch (IOException ignored) {
+            // Fall through to the normalized path comparison.
+        }
+        return first.toAbsolutePath().normalize().equals(second.toAbsolutePath().normalize());
+    }
+
+    private static boolean isOnlyLineBreaks(String text) {
+        for (int i = 0; i < text.length(); i++) {
+            if (text.charAt(i) != '\r' && text.charAt(i) != '\n') {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private static String descriptionFileName(String description) {
+        String normalized = description.replace("\r\n", "\n");
+        Matcher matcher = DESCRIPTION_WORD.matcher(normalized);
+        String word = "rule";
+        while (matcher.find()) {
+            word = matcher.group(1);
+        }
+        String digest = sha256(normalized);
+        String result = "rule_" + word + "_" + digest;
+        if (STORED_RULES_FILE_NAME.equals(result)) {
+            return "rule_" + digest;
+        }
+        return result.length() <= 200 ? result : result.substring(0, 200);
+    }
+
+    private static String sha256(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder(digest.length * 2);
+            for (byte item : digest) {
+                result.append(String.format("%02x", item & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new AssertionError(e);
+        }
+    }
+
+    private enum NameMode {
+        RANDOM, DESCRIPTION, CUSTOM
+    }
+
+    private enum IntegrityMode {
+        REPAIR, FAIL, IGNORE;
+
+        static IntegrityMode from(String value) {
+            if (INTEGRITY_REPAIR.equals(value)) {
+                return REPAIR;
+            }
+            if (INTEGRITY_FAIL.equals(value)) {
+                return FAIL;
+            }
+            if (INTEGRITY_IGNORE.equals(value)) {
+                return IGNORE;
+            }
+            throw new StoreInitializationFailedException(String.format(
+                    "Invalid value for %s='%s'; accepted values are 'repair', 'fail', and 'ignore'",
+                    INTEGRITY_PROPERTY_NAME, value));
+        }
+    }
