+    private static final class StoreState {
+        private final Object lock = new Object();
+        private final Path indexPath;
+        private final Properties properties = new Properties();
+
+        private StoreState(Path indexPath) {
+            this.indexPath = indexPath;
+        }
+
+        private void load(Path path) {
+            properties.clear();
+            try (InputStream input = new FileInputStream(path.toFile())) {
+                properties.load(input);
+            } catch (IOException e) {
+                throw new StoreInitializationFailedException(e);
+            }
+        }
+
+        private void sync() {
+            Path parent = indexPath.getParent();
+            Path temporary = null;
+            try {
+                temporary = Files.createTempFile(parent, ".stored.rules-", ".tmp");
+                try (OutputStream output = Files.newOutputStream(temporary)) {
+                    properties.store(output, "");
+                }
+                try {
+                    Files.move(temporary, indexPath, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
+                } catch (IOException atomicMoveUnsupported) {
+                    Files.move(temporary, indexPath, StandardCopyOption.REPLACE_EXISTING);
+                }
+                temporary = null;
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(e);
+            } finally {
+                if (temporary != null) {
+                    tryDelete(temporary);
+                }
+            }
+        }
+
+        private void tryDelete(Path path) {
+            try {
+                Files.deleteIfExists(path);
+            } catch (IOException ignored) {
+                // Preserve the original sync exception.
+            }
+        }
+    }
