+    private static final class EntryPath {
+        private final boolean valid;
+        private final boolean directRegularFile;
+        private final Path target;
+        private final FileIdentity identity;
+
+        private EntryPath(boolean valid, boolean directRegularFile, Path target, FileIdentity identity) {
+            this.valid = valid;
+            this.directRegularFile = directRegularFile;
+            this.target = target;
+            this.identity = identity;
+        }
+    }
+
+    private static final class PathResolution {
+        private final Path path;
+        private final boolean valid;
+        private final boolean direct;
+        private final boolean regular;
+        private final boolean exists;
+        private final Path target;
+        private final FileIdentity identity;
+
+        private PathResolution(Path path, boolean exists, boolean direct, boolean regular,
+                Path target, FileIdentity identity) {
+            this.path = path;
+            this.valid = path != null;
+            this.exists = exists;
+            this.direct = direct;
+            this.regular = regular;
+            this.target = target;
+            this.identity = identity;
+        }
+    }
+
+    private static final class FileIdentity {
+        private final Object value;
+
+        private FileIdentity(Object value) {
+            this.value = value;
+        }
+
+        @Override
+        public boolean equals(Object other) {
+            return other instanceof FileIdentity && value.equals(((FileIdentity) other).value);
+        }
+
+        @Override
+        public int hashCode() {
+            return value.hashCode();
+        }
+    }
+
+    private static final class IntegrityReport {
+        private final List<Entry> entries;
+        private final List<String> unownedFiles;
+
+        private IntegrityReport(List<Entry> entries, List<String> unownedFiles) {
+            this.entries = entries;
+            this.unownedFiles = unownedFiles;
+        }
+
+        private boolean hasProblems() {
+            return entries.stream().anyMatch(entry -> entry.broken || entry.resolved || entry.shared
+                    || entry.misplaced || entry.occupied || entryDerivedCollision(entry)) || !unownedFiles.isEmpty();
+        }
+
+        private boolean entryDerivedCollision(Entry entry) {
+            if (entry.derivedName == null) {
+                return false;
